// Command deps writes, checks and diffs the non-test package-import edges.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
)

const graph = "docs/dependencies.md"

const header = "# Package dependencies\n\n" +
	"<!-- Generated by `make deps` (tools/deps) from `go list`. Do not edit. -->\n\n" +
	"The import edges from this module's packages under `internal/` and `cmd/`\n" +
	"to other packages of this module. They come from non-test Go files only;\n" +
	"test-only imports are left out. They are listed for `GOOS=linux`\n" +
	"`GOARCH=amd64` with cgo enabled, the platform CI builds for, so the list is\n" +
	"the same on every machine. `make check` fails when this file is stale.\n\n" +
	"A new line here is a new package dependency: say why in the pull request.\n" +
	"CI lists added and removed edges in the CI run's summary, crossing units\n" +
	"first, and annotates added edges on this file with notices. Run\n" +
	"`go -C tools run ./deps --diff origin/main ..` locally for the same list.\n" +
	"This list forbids nothing (module tests and depguard enforce import rules). It does\n" +
	"not show calls through an edge that already exists, dependencies inside one\n" +
	"package, or SQL access to tables.\n\n```text\n"

func main() {
	check := flag.Bool("check", false, "fail when the graph is stale")
	rev := flag.String("diff", "", "list changed edges since a revision")
	flag.Usage = func() { fmt.Fprintln(os.Stderr, "usage: deps [--check | --diff <rev>] <repository root>") }
	flag.Parse()
	diff := false
	flag.Visit(func(f *flag.Flag) { diff = diff || f.Name == "diff" })
	if flag.NArg() != 1 || diff && (*check || *rev == "") {
		flag.Usage()
		os.Exit(2)
	}
	if err := run(flag.Arg(0), *check, *rev, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "deps:", err)
		os.Exit(1)
	}
}

func run(root string, check bool, rev string, out io.Writer) error {
	path := filepath.Join(root, graph)
	if rev != "" {
		// Resolve first: a missing graph is allowed, an unknown revision is not.
		base, err := command(root, "git", "rev-parse", "--verify", "--end-of-options", rev+"^{commit}")
		if err != nil {
			return err
		}
		files, err := command(root, "git", "ls-tree", "--name-only", strings.TrimSpace(base), "--", graph)
		if err != nil {
			return err
		}
		before := ""
		if files != "" {
			before, err = command(root, "git", "show", strings.TrimSpace(base)+":"+graph)
			if err != nil {
				return err
			}
		}
		current, err := os.ReadFile(path)
		if err != nil {
			return fmt.Errorf("reading graph: %w", err)
		}
		if _, err := io.WriteString(out, edgeDiff(before, string(current))); err != nil {
			return fmt.Errorf("writing edge diff: %w", err)
		}
		return nil
	}
	content, err := render(root)
	if err != nil {
		return err
	}
	if check {
		before, err := os.ReadFile(path)
		if err != nil {
			return fmt.Errorf("reading graph: %w", err)
		}
		if string(before) != content {
			return fmt.Errorf("%s is stale: run `make deps` and commit the result", graph)
		}
		return nil
	}
	// A failed generation must not truncate the committed graph.
	defer os.Remove(path + ".tmp")
	if err := os.WriteFile(path+".tmp", []byte(content), 0o644); err != nil {
		return fmt.Errorf("writing graph: %w", err)
	}
	if err := os.Rename(path+".tmp", path); err != nil {
		return fmt.Errorf("replacing graph: %w", err)
	}
	return nil
}

func command(root, name string, args ...string) (string, error) {
	cmd := exec.Command(name, args...)
	cmd.Dir = root
	if name == "go" {
		// Match CI, including cgo files; ignore machine-specific GOFLAGS.
		cmd.Env = append(os.Environ(), "GOOS=linux", "GOARCH=amd64", "CGO_ENABLED=1", "GOFLAGS=")
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("running %s %s: %w\n%s", name, strings.Join(args, " "), err, stderr.String())
	}
	return string(out), nil
}

func render(root string) (string, error) {
	module, err := command(root, "go", "list", "-m")
	if err != nil {
		return "", err
	}
	// .Imports excludes test-only imports (.TestImports and .XTestImports).
	imports, err := command(root, "go", "list", "-f", `{{$p := .ImportPath}}{{range .Imports}}{{$p}} {{.}}{{"\n"}}{{end}}`, "./internal/...", "./cmd/...")
	if err != nil {
		return "", err
	}
	prefix := strings.TrimSpace(module) + "/"
	var edges []string
	for _, line := range strings.Split(imports, "\n") {
		p := strings.Fields(line)
		if len(p) == 2 && strings.HasPrefix(p[1], prefix) {
			edges = append(edges, strings.TrimPrefix(p[0], prefix)+" -> "+strings.TrimPrefix(p[1], prefix))
		}
	}
	slices.Sort(edges)
	body := strings.Join(slices.Compact(edges), "\n")
	if body != "" {
		body += "\n"
	}
	return header + body + "```\n", nil
}

func edges(content string) map[string]bool {
	found := map[string]bool{}
	inside := false
	for _, line := range strings.Split(content, "\n") {
		switch line {
		case "```text":
			inside = true
		case "```":
			inside = false
		default:
			p := strings.Fields(line)
			if inside && len(p) == 3 && p[1] == "->" {
				found[p[0]+" -> "+p[2]] = true
			}
		}
	}
	return found
}

func unit(path string) string {
	p := strings.Split(path, "/")
	if len(p) > 1 && (p[0] == "internal" || p[0] == "cmd") {
		return strings.Join(p[:2], "/")
	}
	return path
}

func edgeDiff(before, current string) string {
	old, now := edges(before), edges(current)
	var changes []string
	for _, change := range []struct {
		kind     string
		from, to map[string]bool
	}{{"Added", now, old}, {"Removed", old, now}} {
		for edge := range change.from {
			if !change.to[edge] {
				group := "1"
				p := strings.Fields(edge)
				if unit(p[0]) == unit(p[2]) {
					group = "2"
				}
				changes = append(changes, group+" "+change.kind+": `"+edge+"`\n")
			}
		}
	}
	if len(changes) == 0 {
		return "No package-import edges changed.\n"
	}
	slices.Sort(changes)
	out, group := "## Package-import edge changes\n", ""
	for _, change := range changes {
		if change[:1] != group {
			group = change[:1]
			label := "Crossing units"
			if group == "2" {
				label = "Within one unit"
			}
			out += "\n### " + label + "\n\n"
		}
		out += "- " + change[2:]
	}
	return out
}
